int calculateMax(int n, bool f, const vector<bool>& a, const vector<int>& memo, const vector<int>& start) {
    int ma = 0;
    for (int i = 1; i <= n; i++) {
        if (a[i]) {
            ma = max(ma, memo[start[i]]);
        } else if (f) {
            int v = memo[start[i - 1]] + (i < n && a[i + 1] ? memo[start[i + 1]] : 0) + (a[i - 1] ? 1 : 0);
            ma = max(ma, v);
        }
    }
    return ma;
}

